def prepare_vertex_coord(data_str):
    x = float(data_str.split(" ")[1])
    y = float(data_str.split(" ")[2])
    z = float(data_str.split(" ")[3])
    return [x, y, z]


def prepare_face_index(data_str):
    data_str = data_str[2:]
    vertex_index = []
    data_block = data_str.split()
    for d in data_block:
        vertex_index.append(int(d.split('/')[0]) - 1)
    return vertex_index


def prepare_lines_index(data_str):
    data_str = data_str[2:]
    vertex_index = []
    data_block = data_str.split()
    for d in data_block:
        vertex_index.append(int(d.split('/')[0]) - 1)
    vertex_index.append(vertex_index[0])
    return vertex_index


for data_str in model_data.split('\n'):
    if data_str.split(' ')[0] == 'v':
        tde4.add3DModelVertex(
            pgroup_id, model_id,
            prepare_vertex_coord(data_str))
    elif data_str.split(' ')[0] == 'f':
        tde4.add3DModelFace(pgroup_id, model_id,
                            prepare_face_index(data_str))
        tde4.add3DModelLine(pgroup_id, model_id,
                            prepare_lines_index(data_str))


tde4.set3DModelName(pgroup_id, model_id, 'Human_180cm')
tde4.set3DModelSurveyFlag(pgroup_id, model_id, 0)
tde4.set3DModelVisibleFlag(pgroup_id, model_id, 1)
tde4.set3DModelRenderingFlags(pgroup_id, model_id, 0, 1, 0)
